import { TriangleAlert } from "lucide-react";
import * as React from "react";
import { Pill } from "@/components/ui/pill";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { cn } from "@/lib/utils";

/**
 * Breakdown content — what a "+N" chip or a total opens.
 *
 * The anatomy is the DS's own, copied from `InvoiceCard` (Figma "Invoice"
 * 27599:62303) — the only hover-card content pattern in the DS, and the one the
 * DS DataTable puts in its Amount column:
 *
 *   flex w-full flex-col gap-4
 *     h4  text-base font-semibold          ← title, foreground (not a muted label)
 *     border-t border-dashed border-border  ← rule under the title
 *     flex flex-col gap-1                   ← detail rows
 *       flex items-center justify-between text-sm text-muted-foreground
 *       …value spans carry tabular-nums
 *     border-t border-dashed border-border  ← rule before the total
 *     flex items-center justify-between text-base font-semibold  ← total
 *
 * The container keeps `HoverCardContent`'s default `p-4`; width is the only
 * override, which is the one the DS itself makes (`w-[380px]` for the Invoice
 * card). Rows with no `value` render as a plain list (the products case).
 */
export interface BreakdownRow {
  label: string;
  /** Omit for a label-only list. */
  value?: string;
  /**
   * A second line under the label — what the row carries (Pavan, 2026-10-14:
   * an asset's products under its name, its capacity as the value).
   */
  sub?: string;
}

/**
 * A GROUPED TABLE instead of rows (Pavan, 2026-10-14 — a ship-to's products,
 * each with its assets, their type and capacity). Same card: title, dashed
 * rule, the card's own type sizes; a header row, then a band per group.
 */
export interface BreakdownTable {
  columns: { label: string; align?: "left" | "right" }[];
  groups: { label: string; rows: string[][] }[];
}

export interface BreakdownCardProps {
  title: string;
  rows: BreakdownRow[];
  table?: BreakdownTable;
  /** Renders the dashed rule + bold total row. Omit to end after the rows. */
  total?: { label: string; value: string };
  /** WARNINGS, after the total (Pavan, 2026-10-20) — red, an alert mark each:
      what the figure means will go wrong. */
  warnings?: string[];
}

export function BreakdownCard({ title, rows, table, total, warnings }: BreakdownCardProps) {
  return (
    <div className="flex w-full flex-col gap-4">
      <h4 className="text-base font-semibold">{title}</h4>
      <div className="border-t border-dashed border-border" />

      {table && (
        <table className="w-full table-fixed text-sm">
          <thead>
            <tr className="text-xs text-muted-foreground">
              {table.columns.map((c) => (
                <th key={c.label} className={cn("pb-1.5 font-medium", c.align === "right" ? "" : "text-left")}>
                  {c.label}
                </th>
              ))}
            </tr>
          </thead>
          {table.groups.map((g) => (
            <tbody key={g.label}>
              {/* THE GROUP — its name on a quiet band across the table; an
                  unnamed group (a plain table) has no band. */}
              {g.label && <tr>
                <td colSpan={table.columns.length} className="pt-2">
                  <span className="block rounded-sm bg-fp-table-header px-2 py-1 text-xs font-semibold text-foreground">
                    {g.label}
                  </span>
                </td>
              </tr>}
              {g.rows.map((r, i) => (
                <tr key={i} className="text-muted-foreground">
                  {r.map((cell, j) => (
                    <td
                      key={j}
                      /* THE NAME TRUNCATES; the rest wrap, so a list of
                         products is read whole. */
                      className={cn(
                        "py-1 pr-2 align-top",
                        j === 0 ? "truncate pl-2 text-foreground" : "break-words",
                        table.columns[j]?.align === "right" && "text-right tabular-nums"
                      )}
                      title={cell}
                    >
                      {cell}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          ))}
        </table>
      )}

      <div className="flex flex-col gap-1">
        {rows.map((row, i) => (
          <div
            key={`${row.label}-${i}`}
            className={cn(
              "flex justify-between gap-6 text-sm text-muted-foreground",
              row.sub ? "items-baseline py-0.5" : "items-center"
            )}
          >
            {row.sub ? (
              <span className="flex min-w-0 flex-col">
                <span className="truncate text-foreground">{row.label}</span>
                <span className="text-xs">{row.sub}</span>
              </span>
            ) : (
              <span className="min-w-0 truncate">{row.label}</span>
            )}
            {row.value && (
              <span className="shrink-0 tabular-nums">{row.value}</span>
            )}
          </div>
        ))}
      </div>

      {total && (
        <>
          <div className="border-t border-dashed border-border" />
          <div className="flex items-center justify-between gap-6 text-base font-semibold">
            <span>{total.label}</span>
            <span className="tabular-nums">{total.value}</span>
          </div>
        </>
      )}

      {warnings && warnings.length > 0 && (
        <ul className="flex flex-col gap-1.5">
          {warnings.map((w) => (
            <li key={w} className="flex items-start gap-2 text-sm text-status-failed">
              <TriangleAlert aria-hidden className="mt-0.5 size-4 shrink-0" />
              <span>{w}</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/*
  ONE WAY TO OPEN A BREAKDOWN, EVERYWHERE (Pavan, 2026-10-14). A "+N" chip —
  or, where the whole cell IS the figure (a quantity), the figure — opens the
  card ON CLICK, above the cell. Not hover: touch cannot hover, and a card
  that appears under a passing pointer is one nobody asked for. The press
  stays in the cell: a row that opens its record on click must not open it
  as well.
*/
export function BreakdownPopover({
  trigger,
  label,
  card,
  width = 280,
  align = "start",
  className,
}: {
  /** The pressable face — a chip, or the figure. */
  trigger: React.ReactNode;
  /** What the press does, for a screen reader. */
  label: string;
  card: BreakdownCardProps;
  width?: number;
  align?: "start" | "end";
  className?: string;
}) {
  return (
    <Popover>
      <PopoverTrigger asChild>
        <button
          type="button"
          aria-label={label}
          onClick={(e) => e.stopPropagation()}
          className={cn(
            "shrink-0 cursor-pointer rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring/50",
            className
          )}
        >
          {trigger}
        </button>
      </PopoverTrigger>
      <PopoverContent
        align={align}
        side="top"
        style={{ width }}
        className="max-h-96 overflow-auto"
        onClick={(e) => e.stopPropagation()}
      >
        <BreakdownCard {...card} />
      </PopoverContent>
    </Popover>
  );
}

/** The "+N" chip that opens a breakdown. */
export function OverflowChip({
  count,
  label,
  card,
  width,
}: {
  count: number;
  label: string;
  card: BreakdownCardProps;
  width?: number;
}) {
  return (
    <BreakdownPopover
      label={label}
      card={card}
      width={width}
      trigger={<Pill className="cursor-pointer tabular-nums">+{count}</Pill>}
    />
  );
}

import * as React from "react";
import { HoverCard as HoverCardPrimitive } from "radix-ui";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

function HoverCard({
  ...props
}: React.ComponentProps<typeof HoverCardPrimitive.Root>) {
  return <HoverCardPrimitive.Root data-slot="hover-card" {...props} />;
}

/**
 * Trigger States — Figma "Hover Card / Trigger" (216:3085). The `link` variant
 * bakes the documented states so call sites don't hand-roll them:
 *   Default → plain · Hover → underline · Focus → ring · Disabled → dimmed.
 * Omit `variant` (or pass `asChild`) for the bare pass-through used when the
 * trigger is a custom element.
 */
const hoverCardTriggerVariants = cva(
  "inline-flex w-fit cursor-pointer items-center rounded-sm font-medium text-foreground underline-offset-4 outline-none transition-colors hover:underline focus-visible:ring-2 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50",
  {
    variants: { variant: { link: "" } },
  }
);

function HoverCardTrigger({
  className,
  variant,
  children,
  asChild,
  ...props
}: React.ComponentProps<typeof HoverCardPrimitive.Trigger> &
  VariantProps<typeof hoverCardTriggerVariants>) {
  // A variant renders its own focusable <button>; without one, pass through
  // (preserving the existing `asChild` API for custom trigger elements).
  if (variant) {
    return (
      <HoverCardPrimitive.Trigger data-slot="hover-card-trigger" asChild>
        <button
          className={cn(hoverCardTriggerVariants({ variant }), className)}
          {...(props as React.ComponentProps<"button">)}
          type="button"
        >
          {children}
        </button>
      </HoverCardPrimitive.Trigger>
    );
  }
  return (
    <HoverCardPrimitive.Trigger
      data-slot="hover-card-trigger"
      className={className}
      asChild={asChild}
      {...props}
    >
      {children}
    </HoverCardPrimitive.Trigger>
  );
}

function HoverCardContent({
  className,
  align = "center",
  sideOffset = 4,
  ...props
}: React.ComponentProps<typeof HoverCardPrimitive.Content>) {
  return (
    <HoverCardPrimitive.Portal data-slot="hover-card-portal">
      <HoverCardPrimitive.Content
        data-slot="hover-card-content"
        align={align}
        sideOffset={sideOffset}
        className={cn(
          "z-50 w-64 origin-(--radix-hover-card-content-transform-origin) rounded-md border border-border bg-popover p-4 text-popover-foreground shadow-md outline-hidden data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95",
          className
        )}
        {...props}
      />
    </HoverCardPrimitive.Portal>
  );
}

export {
  HoverCard,
  HoverCardTrigger,
  HoverCardContent,
  hoverCardTriggerVariants,
};

import * as React from "react";

import { cn } from "@/lib/utils";
import { HoverCard, HoverCardContent, HoverCardTrigger } from "@/components/ui/hover-card";

/*
  THE PILL — the DS's chip and badge (Pavan, 2026-10-09). Trialled on the
  Sales Orders table after the Lovable reference, approved, and promoted here
  as the default for every status, tag, flag and "+N" in Unified View.

  ONE RECIPE, every pill: fully rounded, 28px tall, 12px side padding, 12px
  regular text, no border, a faint tint of the hue behind text in that hue.
  `docs/ds/ui/2-rules.md` §11b.

  COLOUR IS BY KIND (the five kinds of §10b) unless a module lets the user
  choose one — then `color` takes the DS lane palette over the kind.
*/

/** What kind of state a pill says — §10b. The application binds its statuses
 *  to these; the DS never names a status. */
export type PillKind = "neutral" | "info" | "caution" | "success" | "critical";

const KIND_PILL: Record<PillKind, string> = {
  neutral: "bg-muted text-muted-foreground",
  info: "bg-fp-banner-accent-info/10 text-fp-banner-accent-info",
  caution: "bg-fp-banner-accent-caution/10 text-fp-banner-accent-caution",
  success: "bg-status-success/10 text-status-success",
  critical: "bg-status-failed/10 text-status-failed",
};

/*
  A CHOSEN COLOUR (Pavan, 2026-10-09) — for tags whose colour is picked by the
  user (Sales stages, order types) rather than set by meaning. The DS lane
  palette: a faint tint of the hue behind text mixed from that hue and the
  body ink, so it reads in both themes.
*/
export type PillColor =
  | "grey" | "blue" | "yellow" | "green" | "cyan"
  | "purple" | "violet" | "pink" | "orange" | "red";

export const PILL_COLORS: { value: PillColor; label: string }[] = [
  { value: "grey", label: "Grey" },
  { value: "blue", label: "Blue" },
  { value: "yellow", label: "Yellow" },
  { value: "green", label: "Green" },
  { value: "cyan", label: "Cyan" },
  { value: "purple", label: "Purple" },
  { value: "violet", label: "Violet" },
  { value: "pink", label: "Pink" },
  { value: "orange", label: "Orange" },
  { value: "red", label: "Red" },
];

const COLOR_PILL: Record<PillColor, string> = {
  grey: "bg-fp-lane-grey/12 text-[color-mix(in_oklab,var(--color-fp-lane-grey)_70%,var(--foreground))]",
  blue: "bg-fp-lane-blue/12 text-[color-mix(in_oklab,var(--color-fp-lane-blue)_70%,var(--foreground))]",
  yellow: "bg-fp-lane-yellow/18 text-[color-mix(in_oklab,var(--color-fp-lane-yellow)_55%,var(--foreground))]",
  green: "bg-fp-lane-green/12 text-[color-mix(in_oklab,var(--color-fp-lane-green)_60%,var(--foreground))]",
  cyan: "bg-fp-lane-cyan/12 text-[color-mix(in_oklab,var(--color-fp-lane-cyan)_60%,var(--foreground))]",
  purple: "bg-fp-lane-purple/12 text-[color-mix(in_oklab,var(--color-fp-lane-purple)_70%,var(--foreground))]",
  /* THE ACCENT (2026-10-16) — the violet pill is the accent's soft wash and ink. */
  violet: "bg-accent-violet-soft text-accent-violet-ink",
  pink: "bg-fp-lane-pink/12 text-[color-mix(in_oklab,var(--color-fp-lane-pink)_70%,var(--foreground))]",
  orange: "bg-fp-lane-orange/15 text-[color-mix(in_oklab,var(--color-fp-lane-orange)_60%,var(--foreground))]",
  red: "bg-fp-lane-red/12 text-[color-mix(in_oklab,var(--color-fp-lane-red)_70%,var(--foreground))]",
};

/** The shape every pill shares — exported so a chip drawn by another
 *  component (`StatusChip`) cannot drift from it. */
export const PILL_SHAPE =
  "inline-flex h-7 max-w-full shrink-0 items-center rounded-full px-3 text-xs font-normal whitespace-nowrap";

/** The colour classes for a kind, or for a chosen colour over it. */
export function pillColorClass(kind: PillKind = "neutral", color?: PillColor | null) {
  return color ? COLOR_PILL[color] : KIND_PILL[kind];
}

export interface PillProps
  extends Omit<React.HTMLAttributes<HTMLSpanElement>, "children" | "className" | "color"> {
  kind?: PillKind;
  /** A chosen colour, over the kind's. */
  color?: PillColor | null;
  className?: string;
  children: React.ReactNode;
}

export function Pill({ kind = "neutral", color, className, children, ...rest }: PillProps) {
  return (
    <span
      data-slot="pill"
      data-kind={color ? undefined : kind}
      {...rest}
      className={cn(PILL_SHAPE, pillColorClass(kind, color), className)}
    >
      <span className="truncate">{children}</span>
    </span>
  );
}

/**
 * THE FIRST VALUE AS A PILL, the rest behind a "+N" pill that lists them on
 * hover — products and tags on a row.
 */
export function PillList({
  values,
  label,
  kind = "neutral",
}: {
  values: string[];
  label: string;
  kind?: PillKind;
}) {
  if (values.length === 0) return <span className="text-sm text-muted-foreground">—</span>;
  const [first, ...rest] = values;
  return (
    <span className="flex min-w-0 items-center gap-1.5">
      <Pill kind={kind} className="min-w-0 shrink">
        {first}
      </Pill>
      {rest.length > 0 && (
        <HoverCard openDelay={80}>
          <HoverCardTrigger asChild>
            <button
              type="button"
              aria-label={`Show all ${values.length} ${label}`}
              className="shrink-0 rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring/50"
            >
              <Pill kind={kind} className="tabular-nums">
                +{rest.length}
              </Pill>
            </button>
          </HoverCardTrigger>
          <HoverCardContent align="start" className="w-auto max-w-72 p-2">
            <span className="flex flex-wrap gap-1.5">
              {values.map((v) => (
                <Pill key={v} kind={kind}>
                  {v}
                </Pill>
              ))}
            </span>
          </HoverCardContent>
        </HoverCard>
      )}
    </span>
  );
}

"use client"

import * as React from "react"
import { Popover as PopoverPrimitive } from "radix-ui"

import { cn } from "@/lib/utils"

function Popover({
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Root>) {
  return <PopoverPrimitive.Root data-slot="popover" {...props} />
}

function PopoverTrigger({
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Trigger>) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />
}

function PopoverContent({
  className,
  align = "center",
  sideOffset = 4,
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Content>) {
  return (
    <PopoverPrimitive.Portal>
      <PopoverPrimitive.Content
        data-slot="popover-content"
        align={align}
        sideOffset={sideOffset}
        className={cn(
          "z-50 w-72 origin-(--radix-popover-content-transform-origin) rounded-md border bg-popover p-4 text-popover-foreground shadow-md outline-hidden data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95",
          className
        )}
        {...props}
      />
    </PopoverPrimitive.Portal>
  )
}

function PopoverAnchor({
  ...props
}: React.ComponentProps<typeof PopoverPrimitive.Anchor>) {
  return <PopoverPrimitive.Anchor data-slot="popover-anchor" {...props} />
}

function PopoverHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="popover-header"
      className={cn("flex flex-col gap-1 text-sm", className)}
      {...props}
    />
  )
}

function PopoverTitle({ className, ...props }: React.ComponentProps<"h2">) {
  return (
    <div
      data-slot="popover-title"
      className={cn("font-medium", className)}
      {...props}
    />
  )
}

function PopoverDescription({
  className,
  ...props
}: React.ComponentProps<"p">) {
  return (
    <p
      data-slot="popover-description"
      className={cn("text-muted-foreground", className)}
      {...props}
    />
  )
}

export {
  Popover,
  PopoverTrigger,
  PopoverContent,
  PopoverAnchor,
  PopoverHeader,
  PopoverTitle,
  PopoverDescription,
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/** Merge conditional class names and de-dupe Tailwind utilities. */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
